<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import AdminSaveBar from './AdminSaveBar.vue'
import { useAdminEditorState } from '../composables/useAdminEditorState.js'
import { apiRequest } from '../services/api.js'
import { useProductCatalog } from '../services/catalog.js'
import { useArticleCatalog } from '../services/articles.js'
import { useIndustryCatalog } from '../services/industries.js'
import { seoSettings } from '../services/seo.js'
const form=ref(null),loading=ref(false),saving=ref(false),error=ref(''),original=ref(''),tab=ref('pages'),selectedPage=ref('/')
const {products,loadProducts}=useProductCatalog(),{publishedArticles,loadArticles}=useArticleCatalog(),{industries,loadIndustries}=useIndustryCatalog()
const dirty=computed(()=>Boolean(form.value)&&JSON.stringify(form.value)!==original.value)
useAdminEditorState({dirty,saving,loading})
const mainPages=[['/','首页'],['/about','关于我们'],['/solutions','产品中心'],['/insights','新闻资讯'],['/contact','联系我们'],['/site-map','网站地图']]
const options=computed(()=>[
  ...mainPages.map(([path,title])=>({path,title,group:'基础页面',autoTitle:title+' - '+(form.value?.siteName||'TZME 重钢机械'),description:form.value?.defaultDescription||''})),
  ...industries.value.filter(item=>item.status==='published'&&products.value.some(product=>product.status==='published'&&product.industries.includes(item.id))).map(item=>({path:'/solutions?industry='+item.id,title:item.titleZh,group:'应用行业',autoTitle:item.titleZh+'装备 - '+form.value?.siteName,description:'根据行业关联的已发布产品自动生成。'})),
  ...products.value.filter(item=>item.status==='published').map(item=>({path:'/solutions/'+item.id,title:item.titleZh,group:'产品资料',autoTitle:item.titleZh+'｜设备介绍与制造服务 - '+form.value?.siteName,description:item.summaryZh||form.value?.defaultDescription||''})),
  ...publishedArticles.value.map(item=>({path:'/insights/'+item.id,title:item.titleZh,group:'新闻资讯',autoTitle:item.titleZh+' - '+form.value?.siteName,description:item.summaryZh||form.value?.defaultDescription||''})),
])
const currentOption=computed(()=>options.value.find(item=>item.path===selectedPage.value))
const currentPage=computed(()=>form.value?.pages[selectedPage.value]||form.value?.overrides[selectedPage.value])
function updatePage(key,value){
  const target=form.value.pages[selectedPage.value]||form.value.overrides[selectedPage.value]||{title:'',description:''}
  target[key]=value
  if(!form.value.pages[selectedPage.value]){if(!target.title&&!target.description)delete form.value.overrides[selectedPage.value];else form.value.overrides[selectedPage.value]=target}
}
function autoPage(){if(form.value.pages[selectedPage.value]){form.value.pages[selectedPage.value]={title:'',description:''}}else delete form.value.overrides[selectedPage.value]}
async function load(){loading.value=true;error.value='';try{const [value]=await Promise.all([apiRequest('/api/seo/settings/admin'),loadProducts(),loadArticles(),loadIndustries()]);form.value=value;original.value=JSON.stringify(value)}catch(failure){error.value=failure.message}finally{loading.value=false}}
async function save(){if(saving.value||!form.value)return;saving.value=true;error.value='';try{const saved=await apiRequest('/api/seo/settings/admin',{method:'PUT',body:form.value});form.value=saved;original.value=JSON.stringify(saved);seoSettings.value={siteUrl:saved.siteUrl,siteName:saved.siteName,icpNumber:saved.icpNumber,verification:saved.verification};ElMessage.success('搜索展示配置已保存，公开页面、问答和站点地图同步使用最新资料。')}catch(failure){error.value=failure.message;ElMessage.error(failure.message)}finally{saving.value=false}}
function moveFaq(index,offset){const target=index+offset;if(target<0||target>=form.value.faqs.length)return;const item=form.value.faqs.splice(index,1)[0];form.value.faqs.splice(target,0,item)}
onMounted(load);defineExpose({load})
</script>
<template>
  <section v-loading="loading" class="seo-manager">
    <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
    <template v-if="form">
      <el-tabs v-model="tab">
        <el-tab-pane label="页面标题与摘要" name="pages"><div class="seo-page-grid"><div class="seo-card"><h2>选择要维护的页面</h2><el-select v-model="selectedPage" filterable aria-label="选择搜索展示页面"><el-option-group v-for="group in ['基础页面','应用行业','产品资料','新闻资讯']" :key="group" :label="group"><el-option v-for="item in options.filter(option=>option.group===group)" :key="item.path" :value="item.path" :label="item.title"/></el-option-group></el-select><el-form label-position="top" :disabled="saving"><el-form-item label="搜索结果标题"><el-input :model-value="currentPage?.title||''" :placeholder="currentOption?.autoTitle" maxlength="160" show-word-limit @update:model-value="updatePage('title',$event)"/><p class="seo-hint">围绕页面实际内容填写，避免反复堆叠地区或产品词。</p></el-form-item><el-form-item label="页面摘要"><el-input :model-value="currentPage?.description||''" :placeholder="currentOption?.description" type="textarea" :rows="4" maxlength="400" show-word-limit @update:model-value="updatePage('description',$event)"/><p class="seo-hint">产品和新闻留空时，自动采用对应后台资料。无需逐个填写。</p></el-form-item></el-form><el-button text @click="autoPage">恢复自动生成</el-button></div><aside class="seo-card seo-search-preview"><span>标题与摘要预览</span><p class="seo-preview-url">{{ form.siteUrl+selectedPage }}</p><h3>{{ currentPage?.title||currentOption?.autoTitle }}</h3><p>{{ currentPage?.description||currentOption?.description }}</p><small>搜索平台可能根据用户查询调整标题或摘要，以上为填写效果。</small><a :href="selectedPage" target="_blank" rel="noopener noreferrer">查看已保存页面 ↗</a></aside></div></el-tab-pane>
        <el-tab-pane label="网站基础资料" name="site"><div class="seo-card"><el-form label-position="top" :disabled="saving"><div class="seo-fields"><el-form-item label="中文版正式域名"><el-input v-model="form.siteUrl" placeholder="https://www.tzme.net"/><p class="seo-hint">用于规范链接、站点地图及企业标识。修改正式域名前需确认真实部署地址。</p></el-form-item><el-form-item label="网站简称"><el-input v-model="form.siteName" maxlength="60"/></el-form-item><el-form-item label="默认网站介绍"><el-input v-model="form.defaultDescription" type="textarea" :rows="3" maxlength="300" show-word-limit/></el-form-item><el-form-item label="ICP备案号（可选）"><el-input v-model="form.icpNumber" maxlength="80" placeholder="填写实际备案号"/><p class="seo-hint">有真实备案号后填写，页脚会显示工信部查询入口；未填写时不展示。</p></el-form-item></div></el-form><p class="seo-hint">企业名称采用官网现有公司名称；地址、电话和邮箱沿用“企业与联系方式”，制造与资质事实沿用原有资料。</p><router-link to="/admin/contact">维护企业联系方式 ↗</router-link></div></el-tab-pane>
        <el-tab-pane label="制造服务问答" name="questions"><div class="seo-card"><div class="seo-faq-toolbar"><div><h2>公开的制造服务问答</h2><p>显示在关于我们、产品及联系页面，同时用于结构化资料。请依据实际能力填写。</p></div><el-switch v-model="form.faqEnabled" active-text="展示问答"/></div><article v-for="(item,index) in form.faqs" :key="index" class="seo-faq-editor"><header><strong>{{ String(index+1).padStart(2,'0') }} / 常见问题</strong><div><el-button text :disabled="saving||index===0" @click="moveFaq(index,-1)">上移</el-button><el-button text :disabled="saving||index===form.faqs.length-1" @click="moveFaq(index,1)">下移</el-button><el-button text type="danger" :disabled="saving" @click="form.faqs.splice(index,1)">删除</el-button></div></header><el-form label-position="top" :disabled="saving"><el-form-item label="问题"><el-input v-model="item.question" maxlength="150"/></el-form-item><el-form-item label="回答"><el-input v-model="item.answer" type="textarea" :rows="3" maxlength="1200" show-word-limit/></el-form-item></el-form></article><el-button :disabled="saving||form.faqs.length>=12" @click="form.faqs.push({question:'',answer:''})">新增问题</el-button><p class="seo-hint">产品适用场景和行业产品清单会依据已发布的资料自动补充，不增加未经证实的价格、参数或交期承诺。</p></div></el-tab-pane>
        <el-tab-pane label="搜索平台验证" name="verification"><div class="seo-card"><h2>网站归属验证</h2><p class="seo-hint">在对应平台添加 www.tzme.net，选择 HTML 标签验证，仅将标签中的 content 值填入这里；保存后再到平台点击验证。</p><el-form label-position="top" :disabled="saving"><div class="seo-fields"><el-form-item v-for="[key,label] in [['baidu','百度搜索资源平台'],['bing','必应站长工具'],['so360','360站长平台'],['sogou','搜狗站长平台']]" :key="key" :label="label"><el-input v-model="form.verification[key]" maxlength="200" placeholder="填写验证 content 值"/></el-form-item></div></el-form><div class="seo-discovery-links"><a href="/robots.txt" target="_blank" rel="noopener">查看 robots.txt ↗</a><a href="/sitemap.xml" target="_blank" rel="noopener">查看 XML 站点地图 ↗</a><a href="/llms.txt" target="_blank" rel="noopener">查看公开资料索引 ↗</a></div><p class="seo-hint">站点地图仅列出已发布页面和有产品的行业，自动跟随资料更新。平台验证、提交和实际收录结果需要在相应平台完成。</p></div></el-tab-pane>
      </el-tabs>
      <AdminSaveBar :dirty="dirty" :saving="saving" :disabled="loading" @save="save"/>
    </template>
  </section>
</template>
<style scoped>
.seo-manager{min-height:320px}.seo-manager>.el-alert{margin-bottom:20px}.seo-page-grid{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,.9fr);gap:25px}.seo-card{border:1px solid #e0e8ed;background:#fff;border-radius:10px;padding:25px;margin-top:15px}.seo-card h2{font-size:16px;line-height:1.6;color:#23485d;margin:0 0 20px}.seo-card>.el-select{width:100%;margin-bottom:25px}.seo-fields{display:grid;grid-template-columns:1fr 1fr;gap:0 25px}.seo-hint{font-size:11px;line-height:1.9;color:#7b919f;margin:9px 0}.seo-card a{font-size:12px;color:#087f91;text-decoration:none}.seo-search-preview{align-self:start;position:sticky;top:20px}.seo-search-preview>span{font-size:11px;color:#8296a4}.seo-preview-url{font-size:12px;line-height:1.8;color:#49836b;overflow-wrap:anywhere;margin-top:24px}.seo-search-preview h3{font-size:18px;line-height:1.6;color:#225a9b;margin:10px 0}.seo-search-preview>p:not(.seo-preview-url){font-size:13px;line-height:1.9;color:#5c7486;overflow-wrap:anywhere}.seo-search-preview>small{display:block;font-size:11px;line-height:1.8;color:#8a9da8;border-top:1px solid #edf1f4;margin-top:25px;padding-top:17px}.seo-search-preview>a{display:inline-block;margin-top:20px}.seo-faq-toolbar{display:flex;align-items:start;justify-content:space-between;gap:30px;margin-bottom:25px}.seo-faq-toolbar h2{margin-bottom:8px}.seo-faq-toolbar p{font-size:12px;color:#7b919f;line-height:1.8;margin:0}.seo-faq-editor{padding:20px;border:1px solid #e1e9ee;border-radius:7px;margin-bottom:18px}.seo-faq-editor>header{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:20px}.seo-faq-editor strong{font-size:12px;color:#496a7e}.seo-discovery-links{display:flex;gap:25px;flex-wrap:wrap;border-top:1px solid #e1e9ee;padding-top:20px;margin-top:10px}@media(max-width:1000px){.seo-page-grid{grid-template-columns:1fr}.seo-search-preview{position:static}.seo-fields{grid-template-columns:1fr}}@media(max-width:700px){.seo-card{padding:18px}.seo-faq-toolbar{flex-direction:column;gap:15px}.seo-faq-editor{padding:15px}.seo-faq-editor>header{align-items:start}.seo-faq-editor>header>div{display:flex;flex-wrap:wrap}.seo-faq-editor header .el-button{padding:3px;font-size:11px}}
</style>
